treams[0].strf{*width=88;}expected.streams[0].strl_extra[0].fourcc="edited 世界".into();expected.streams[0].chunks[0].keyframe=false;expected.main_header.reserved[4]=99;assert_eq!(AviSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}
