test("AVI large retained bytes and ordered chunks remain bounded and cancellable",async()=>{const snapshot=structuredClone(fixture);snapshot.streams[0]!.chunks=Array.from({length:controls.entityCount},()=>({...snapshot.streams[0]!.chunks[0]!}));const cancel=new AbortController();let reached=false;await expect(aviSnapshotToSqliteDatabase(snapshot as AviSnapshot,{signal:cancel.signal,onProgress:event=>{if(event.completed>=controls.cancelAt){reached=true;cancel.abort()}}})).rejects.toHaveProperty("kind",canceledKind);expect(reached).toBe(true);const large=parseAviSnapshot(fixture);large.streams[0]!.strh.strhExtra=Array(controls.largeBlobBytes).fill(255);await expect(aviSnapshotToSqliteDatabase(large,{maxValueBytes:controls.largeBlobBytes-1})).rejects.toThrow();const copyCancel=new AbortController();let copyReached=false;await expect(aviSnapshotToSqliteDatabase(large,{signal:copyCancel.signal,onProgress:event=>{if(event.phase==="projectSnapshot"&&event.completed===0&&event.total===controls.largeBlobBytes){copyReached=true;copyCancel.abort()}}})).rejects.toHaveProperty("kind",canceledKind);expect(copyReached).toBe(true);});
test("AVI independent GraphQL retains every native header and format width",async()=>{for(const path of["../../🔗️.graphql","../../📝️text/🔗️.graphql"]){const sdl=await Bun.file(new URL(path,import.meta.url)).text();const schema=buildSchema("enum StateClass{ARTIFACT} directive @state(class:StateClass!) on FIELD_DEFINITION "+sdl+" type Query{snapshot:AviSnapshot!}");const format=schema.getType("AviStreamFormat");if(!isUnionType(format))throw Error("AVI format union is missing");format.resolveType=value=>value.format==="bitmapInfo"?"AviBitmapInfo":value.format==="waveFormat"?"AviWaveFormat":"AviRawFormat";const result=graphqlSync({schema,source:"{snapshot{schema mainHeader{microSecPerFrame maxBytesPerSec paddingGranularity flags totalFrames initialFrames streams suggestedBufferSize width height reserved} streams{strh{fccType fccHandler flags priority language initialFrames scale rate start length suggestedBufferSize quality sampleSize rcFrameLeft rcFrameTop rcFrameRight rcFrameBottom rcFrameWidth strhExtra} strf{... on AviBitmapInfo{format size width height planes bitCount compression sizeImage xPelsPerMeter yPelsPerMeter colorsUsed colorsImportant} ... on AviWaveFormat{format formatTag channels samplesPerSec avgBytesPerSec blockAlign bitsPerSample extra} ... on AviRawFormat{format data}} chunks{fourcc data keyframe} strlExtra{fourcc data}} idx1Present unknownChunks{fourcc data} hdrlExtra{fourcc data}}}",rootValue:{snapshot:fixture}});expect(result.errors).toBeUndefined();expect(result.data?.snapshot).toEqual(fixture);}});
test("AVI adjacent owned representation consumers retain the complete neutral state",()=>{const text:TextSnapshot=parseTextSnapshot(fixture);const binary:BinarySnapshot=parseBinarySnapshot(fixture);expect(text.hdrlExtra).toEqual(fixture.hdrlExtra);expect(binary.streams[0]!.strh.strhExtra).toEqual(fixture.streams[0]!.strh.strhExtra);expect(binary.streams[0]!.strlExtra).toEqual(fixture.streams[0]!.strlExtra);for(const facet of[artifactSchema,textSchema]){const ajv=new Ajv({strict:false}).addSchema(schema);expect(ajv.validate(facet,fixture)).toBe(true);const invalid=structuredClone(fixture);invalid.streams[0]!.strh.rcFrameWidth=256;expect(ajv.validate(facet,invalid)).toBe(false);}});

